INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10006, /*where_type*/2002, /*character_id*/127702, /*face_type*/2, /*character_name*/'琳德', /*description*/'商店的扫除无可挑剔。\n作为公主殿下的直营商店，\n这是理所当然的', /*voice_id*/2, /*start_time*/'2025/06/30 11:00:00', /*end_time*/'2025/08/21 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/2, /*season_id*/2);
INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10007, /*where_type*/2002, /*character_id*/127802, /*face_type*/1, /*character_name*/'维尔姆', /*description*/'欢迎光临商店。\n在可以用驾车游币交换物品。\n请随意看看', /*voice_id*/1, /*start_time*/'2025/06/30 11:00:00', /*end_time*/'2025/08/21 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*season_id*/2);
